predicted_sql:
SELECT e.Name
FROM employee e
WHERE NOT EXISTS (
    SELECT 1 FROM evaluation v WHERE v.Employee_ID = e.Employee_ID
);

SELECT p.professional_id, p.role_code, p.email_address
FROM Professionals p
WHERE p.professional_id NOT IN (SELECT t.professional_id FROM Treatments t WHERE t.professional_id IS NOT NULL);

SELECT professional_id, role_code, email_address
FROM Professionals
WHERE professional_id NOT IN (SELECT professional_id FROM Treatments WHERE professional_id IS NOT NULL);

SELECT DISTINCT r.property_type_description
FROM Ref_Property_Types r
JOIN Properties p ON p.property_type_code = r.property_type_code;

SELECT DISTINCT c.course_name
FROM Courses c
JOIN Student_Enrolment_Courses sec ON c.course_id = sec.course_id;
